import pytest
from tokenopt.utils.messages import get_user_query


def test_single_user_message():
    messages = [{"role": "user", "content": "Hello"}]
    assert get_user_query(messages) == "Hello"


def test_mixed_roles_last_user():
    messages = [
        {"role": "system", "content": "You are helpful"},
        {"role": "assistant", "content": "Hi there"},
        {"role": "user", "content": "How are you?"}
    ]
    assert get_user_query(messages) == "How are you?"


def test_no_user_message():
    messages = [
        {"role": "system", "content": "System prompt"},
        {"role": "assistant", "content": "Assistant response"}
    ]
    assert get_user_query(messages) == ""


def test_non_string_content():
    messages = [{"role": "user", "content": {"key": "value"}}]
    assert get_user_query(messages) == ""

